class MyLinkedList:
    def __init__(self):
        self.data = []                                                     # a plain Python list simulates the linked list's values

    def get(self, index):
        if index < 0 or index >= len(self.data):
            return -1
        return self.data[index]

    def add_at_head(self, val):
        self.data.insert(0, val)                                           # O(n) shift, since everything after index 0 must move

    def add_at_tail(self, val):
        self.data.append(val)

    def add_at_index(self, index, val):
        if index > len(self.data):
            return
        if index < 0:
            index = 0
        self.data.insert(index, val)                                       # O(n) shift for any index other than the very end

    def delete_at_index(self, index):
        if 0 <= index < len(self.data):
            self.data.pop(index)                                           # O(n) shift, since everything after index must move


if __name__ == "__main__":
