import java.util.*;

public class Main {
    class MyLinkedList {
        List<Integer> data = new ArrayList<>();                                     // a plain ArrayList simulates the linked list's values

        int get(int index) {
            if (index < 0 || index >= data.size()) return -1;
            return data.get(index);
        }

        void addAtHead(int val) {
            data.add(0, val);                                                          // O(n) shift, since everything after index 0 must move
        }

        void addAtTail(int val) {
            data.add(val);
        }

        void addAtIndex(int index, int val) {
            if (index > data.size()) return;
            if (index < 0) index = 0;
            data.add(index, val);                                                      // O(n) shift for any index other than the very end
        }

        void deleteAtIndex(int index) {
            if (index >= 0 && index < data.size()) data.remove(index);                    // O(n) shift, since everything after index must move
        }
    }

    public static void main(String[] args) {
        MyLinkedList ll = new MyLinkedList();
        ll.addAtHead(1);
        ll.addAtTail(3);
        ll.addAtIndex(1, 2);
        System.out.println(ll.get(1));
        ll.deleteAtIndex(1);
        System.out.println(ll.get(1));
    }
}

