#include <bits/stdc++.h>
using namespace std;

class MyLinkedList {
public:
    vector<int> data;                                                                 // a plain vector simulates the linked list's values

    int get(int index) {
        if (index < 0 || index >= (int)data.size()) return -1;
        return data[index];
    }

    void addAtHead(int val) {
        data.insert(data.begin(), val);                                                  // O(n) shift, since everything after index 0 must move
    }

    void addAtTail(int val) {
        data.push_back(val);
    }

    void addAtIndex(int index, int val) {
        if (index > (int)data.size()) return;
        if (index < 0) index = 0;
        data.insert(data.begin() + index, val);                                            // O(n) shift for any index other than the very end
    }

    void deleteAtIndex(int index) {
        if (index >= 0 && index < (int)data.size()) data.erase(data.begin() + index);         // O(n) shift, since everything after index must move
    }
};

