    MyLinkedList ll;
    ll.addAtHead(1);
    ll.addAtTail(3);
    ll.addAtIndex(1, 2);
    cout << ll.get(1) << endl;
    ll.deleteAtIndex(1);
    cout << ll.get(1) << endl;
    return 0;
