class ListNode:
    def __init__(self, val=0):
        self.val = val
        self.prev = None
        self.next = None

class MyLinkedList:
    def __init__(self):
        self.head = ListNode()                                              # dummy head sentinel (never holds real data)
        self.tail = ListNode()                                              # dummy tail sentinel (never holds real data)
        self.head.next = self.tail
        self.tail.prev = self.head
        self.size = 0

    def _node_at(self, index):
        if index < self.size // 2:                                         # walk from whichever END is closer to index
            node = self.head.next
            for _ in range(index):
                node = node.next
        else:
            node = self.tail.prev
            for _ in range(self.size - 1 - index):
                node = node.prev
        return node

    def get(self, index):
        if index < 0 or index >= self.size:
            return -1
        return self._node_at(index).val

    def add_at_head(self, val):
        self._insert_before(self.head.next, val)

    def add_at_tail(self, val):
        self._insert_before(self.tail, val)

    def add_at_index(self, index, val):
        if index > self.size:
            return
        if index < 0:
            index = 0
        target = self.tail if index == self.size else self._node_at(index)
        self._insert_before(target, val)

    def delete_at_index(self, index):
        if index < 0 or index >= self.size:
            return
        node = self._node_at(index)
        node.prev.next = node.next
        node.next.prev = node.prev
        self.size -= 1

    def _insert_before(self, node, val):
        new_node = ListNode(val)
        new_node.prev = node.prev
        new_node.next = node
        node.prev.next = new_node
        node.prev = new_node
        self.size += 1


if __name__ == "__main__":
    ll = MyLinkedList()
    ll.add_at_head(1)
    ll.add_at_tail(3)
    ll.add_at_index(1, 2)
    print(ll.get(1))
    ll.delete_at_index(1)
    print(ll.get(1))

