import java.util.*;

public class Main {
    class ListNode {
        int val;
        ListNode prev, next;
        ListNode(int val) { this.val = val; }
    }

    class MyLinkedList {
        ListNode head = new ListNode(0);                                                // dummy head sentinel (never holds real data)
        ListNode tail = new ListNode(0);                                                // dummy tail sentinel (never holds real data)
        int size = 0;

        MyLinkedList() {
            head.next = tail;
            tail.prev = head;
        }

        ListNode nodeAt(int index) {
            ListNode node;
            if (index < size / 2) {                                                       // walk from whichever END is closer to index
                node = head.next;
                for (int i = 0; i < index; i++) node = node.next;
            } else {
                node = tail.prev;
                for (int i = 0; i < size - 1 - index; i++) node = node.prev;
            }
            return node;
        }

        int get(int index) {
            if (index < 0 || index >= size) return -1;
            return nodeAt(index).val;
        }

        void addAtHead(int val) { insertBefore(head.next, val); }

        void addAtTail(int val) { insertBefore(tail, val); }

        void addAtIndex(int index, int val) {
            if (index > size) return;
            if (index < 0) index = 0;
            ListNode target = (index == size) ? tail : nodeAt(index);
            insertBefore(target, val);
        }

        void deleteAtIndex(int index) {
            if (index < 0 || index >= size) return;
            ListNode node = nodeAt(index);
            node.prev.next = node.next;
            node.next.prev = node.prev;
            size--;
        }

        void insertBefore(ListNode node, int val) {
            ListNode newNode = new ListNode(val);
            newNode.prev = node.prev;
            newNode.next = node;
            node.prev.next = newNode;
            node.prev = newNode;
            size++;
        }
    }

    public static void main(String[] args) {
        MyLinkedList ll = new MyLinkedList();
        ll.addAtHead(1);
        ll.addAtTail(3);
        ll.addAtIndex(1, 2);
        System.out.println(ll.get(1));
        ll.deleteAtIndex(1);
        System.out.println(ll.get(1));
